// Generated by `vumlo-cli brand apply` from the configuration schema. Do not edit.
export type ClientConfig = {
  /** Where the web app reaches the API: `server.public_origin` + `/api/v1`. */
  api_url: string;
  /** What the desktop app and the web app's sign-in page agree on (ADR-0062). */
  desktop: {
    /** The scheme of the app's links, `vumlo-ucu` for `vumlo-ucu://course?id=...`. */
    url_scheme: string;
  };
  /** The generated logo, relative to the generated directory. Absent without `institution.logo`. */
  logo?: string | null;
  /** Every optional module of this build line and whether it is on. */
  modules: { [name: string]: "enabled" | "disabled" | "unavailable" };
  /** The keys marked `public` in the configuration schema. */
  public: {
    institution: {
      /** How points relate to the grade (ADR-0022). */
      grading_scale: "twelve" | "hundred";
      /** The interface language an institution starts in (ADR-0043, ADR-0044). */
      language: "en" | "uk";
      name: string;
      short_name: string;
      /** An IANA zone name, e.g. `Europe/Kyiv`. */
      time_zone: string;
    };
    server: {
      public_origin: string;
    };
  };
  /** The Vumlo release the file was generated by. */
  version: string;
  /** The enabled modules that have UI in the web app: only these are built into the web bundle. */
  web_modules: (string)[];
};
